package com.taskmanager.backend.model;

public class User {

    // Unique ID generated by MySQL
    private Long id;

    // User's display name
    private String name;

    // Email uniquely identifies the user
    private String email;

    // Stores the BCrypt hash, never the original password
    private String passwordHash;

    // Required for frameworks and object mapping
    public User() {
    }

    // Constructor for existing user data without a password hash
    public User(Long id, String name, String email) {
        this.id = id;
        this.name = name;
        this.email = email;
    }

    // Constructor that also accepts a password hash
    public User(Long id, String name, String email, String passwordHash) {
        this.id = id;
        this.name = name;
        this.email = email;
        this.passwordHash = passwordHash;
    }

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public String getPasswordHash() {
        return passwordHash;
    }

    public void setPasswordHash(String passwordHash) {
        this.passwordHash = passwordHash;
    }
}